const fs = require('fs');

const UP = 0, DOWN = 1, LEFT = 2, RIGHT = 3;
const UPLEFT = 4, UPRIGHT = 5, DOWNLEFT = 6, DOWNRIGHT = 7;

const dx = [0, 0, -1, 1, -1, 1, -1, 1];
const dy = [1, -1, 0, 0, 1, 1, -1, -1];

const MAX = 5 * 30 + 5; // 155

function rot(dir) {
    if (dir === UP) return [UPLEFT, UPRIGHT];
    if (dir === DOWN) return [DOWNLEFT, DOWNRIGHT];
    if (dir === LEFT) return [UPLEFT, DOWNLEFT];
    if (dir === RIGHT) return [UPRIGHT, DOWNRIGHT];
    if (dir === UPLEFT) return [UP, LEFT];
    if (dir === UPRIGHT) return [UP, RIGHT];
    if (dir === DOWNLEFT) return [DOWN, LEFT];
    if (dir === DOWNRIGHT) return [DOWN, RIGHT];
    return [0, 0];
}

function solve() {
    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (input.length === 0) return;
    let ptr = 0;
    const n = parseInt(input[ptr++], 10);
    const t = [0]; // 1-indexed
    for (let i = 1; i <= n; i++) {
        t.push(parseInt(input[ptr++], 10));
    }

    let ans = 0;
    // Use Set for sparse visited states: "x,y,dir,lev,far"
    const marked = new Set();
    // Use Set for visited cells: "x,y"
    const visitedCells = new Set();

    // Queue implemented as array with head index for O(1) pop
    const queue = [];
    let head = 0;

    const startX = MAX, startY = MAX;
    const startKey = `${startX},${startY},${UP},1,1`;
    marked.add(startKey);
    visitedCells.add(`${startX},${startY}`);
    ans++;
    queue.push([startX, startY, UP, 1, 1]);

    while (head < queue.length) {
        const [x, y, dir, lev, far] = queue[head++];

        // Count unique cells (already counted on push, but logic in C++ checks on pop)
        // C++ code checks mp on pop. Since we add to visitedCells on push, we don't need to check here.
        // However, C++ code increments ans only if not in mp.
        // In JS, we add to visitedCells when pushing to queue (or when popping).
        // To match C++ exactly: C++ marks mp and increments ans when popping if not already marked.
        // But C++ marks marked[][][][][] on push.
        // Let's replicate: check visitedCells on pop.
        const cellKey = `${x},${y}`;
        if (!visitedCells.has(cellKey)) {
            visitedCells.add(cellKey);
            ans++;
        }

        if (lev === n + 1) continue;

        if (far !== t[lev]) {
            const nx = x + dx[dir];
            const ny = y + dy[dir];
            const nfar = far + 1;
            const stateKey = `${nx},${ny},${dir},${lev},${nfar}`;
            if (!marked.has(stateKey)) {
                marked.add(stateKey);
                queue.push([nx, ny, dir, lev, nfar]);
            }
        } else {
            const [d1, d2] = rot(dir);
            const nlev = lev + 1;
            const nfar = 0;

            const key1 = `${x},${y},${d1},${nlev},${nfar}`;
            if (!marked.has(key1)) {
                marked.add(key1);
                queue.push([x, y, d1, nlev, nfar]);
            }

            const key2 = `${x},${y},${d2},${nlev},${nfar}`;
            if (!marked.has(key2)) {
                marked.add(key2);
                queue.push([x, y, d2, nlev, nfar]);
            }
        }
    }

    console.log(ans);
}

solve();

